"""Danish vocabulary sets used by the staged curriculum."""
from app.data._types import VocabularySet,VocabularyEntry
def _w(word,pos,definition,example): return VocabularyEntry(word=word,pos=pos,definition=definition,example=example)
_BANK={
"A1":[("hilsen","phrase","en venlig indledning","En hilsen til dig."),("navn","noun","det man kaldes","Mit navn er Sara."),("familie","noun","mennesker man er i familie med","Min familie bor her."),("morgen","noun","den første del af dagen","Jeg arbejder om morgenen."),("klokken","noun","angivelse af tid","Hvad er klokken?"),("aftale","noun","noget man har planlagt","Vi har en aftale."),("brød","noun","mad lavet af mel","Jeg køber brød."),("betale","verb","give penge for noget","Jeg vil betale nu.")],
"A2":[("lejlighed","noun","bolig i en bygning","Jeg bor i en lejlighed."),("station","noun","sted hvor tog eller busser stopper","Vi mødes på stationen."),("billet","noun","dokument der giver adgang til en rejse","Jeg har købt en billet."),("læge","noun","person der behandler sygdom","Jeg skal til lægen."),("sund","adjective","i god fysisk tilstand","Hun er sund og aktiv."),("arbejde","noun","beskæftigelse eller opgave","Mit arbejde begynder klokken otte."),("fritid","noun","tid uden arbejde eller skole","Jeg læser i min fritid."),("rejse","verb","tage fra et sted til et andet","Vi rejser i weekenden.")],
"B1":[("uddannelse","noun","organiseret læring og studier","Hun tager en videregående uddannelse."),("erfaring","noun","viden fra tidligere oplevelser","Han har meget erfaring."),("nyhed","noun","ny information om en begivenhed","Jeg læste nyheden i morges."),("samfund","noun","et organiseret fællesskab","Samfundet ændrer sig."),("følelse","noun","indre oplevelse eller emotion","Det er en stærk følelse."),("forhold","noun","relation mellem mennesker eller ting","De har et godt forhold."),("mulighed","noun","noget der kan lade sig gøre","Det er en god mulighed."),("beslutte","verb","vælge efter overvejelse","Vi må beslutte os snart.")],
"B2":[("argument","noun","grund der støtter en påstand","Hun fremsatte et stærkt argument."),("debat","noun","struktureret udveksling af synspunkter","Debatten fortsatte længe."),("ledelse","noun","at styre en organisation eller gruppe","God ledelse kræver tillid."),("kultur","noun","fælles værdier og praksisser","Kultur påvirker sproget."),("identitet","noun","opfattelse af hvem man er","Sprog er en del af identiteten."),("problem","noun","noget der kræver en løsning","Vi skal løse problemet."),("løsning","noun","svar på et problem","Vi fandt en løsning."),("påvirke","verb","have indflydelse på noget","Medier kan påvirke holdninger.")],
"C1":[("nuance","noun","fin forskel i betydning","Der er en vigtig nuance."),("analyse","noun","grundig undersøgelse","Analysen viser flere årsager."),("formidling","noun","at gøre information forståelig","God formidling kræver klarhed."),("faglig","adjective","som vedrører et fagområde","Hun skrev en faglig rapport."),("sammenhæng","noun","forbindelse mellem dele","Vi må forstå sammenhængen."),("vurdering","noun","overvejet bedømmelse","Rapporten indeholder en vurdering."),("antagelse","noun","noget man tager for givet","Det er en vigtig antagelse."),("konsekvens","noun","resultat af en handling","Beslutningen fik en uventet konsekvens.")],
"C2":[("præcision","noun","nøjagtighed i udtryk eller handling","Præcision er vigtig i teksten."),("retorik","noun","kunsten at overbevise gennem sprog","Retorik bruges i debatter."),("perspektiv","noun","måde at se en sag på","Vi bør undersøge sagen fra flere perspektiver."),("fortolkning","noun","forklaring af betydning","Fortolkningen afhænger af konteksten."),("forudsætning","noun","betingelse der må være opfyldt","Tillid er en vigtig forudsætning."),("modsigelse","noun","udsagn der ikke kan være sande samtidig","Der er en tydelig modsigelse."),("sammenfatte","verb","gengive hovedpunkterne kort","Kan du sammenfatte argumentet?"),("distinktion","noun","klar forskel mellem begreber","Teksten kræver en fin distinktion.")]}
VOCABULARY_SETS=[]
for level,rows in _BANK.items():
    for i,(word,pos,definition,example) in enumerate(rows,1):
        VOCABULARY_SETS.append(VocabularySet(id=f"da-{level.lower()}-{i}",level=level,topic=word.capitalize(),unit_ref=f"{level.lower()}-unit-{((i-1)%4)+1}",words=[_w(word,pos,definition,example)]))
